import { isScssVariable } from "../isScssVariable/index.js";
/**
 * Asks whether a declaration is plain CSS.
 * @param decl - The declaration.
 * @returns True where it is.
 */
export function isStandardSyntaxDeclaration(decl) {
    // A `$` variable is Sass's or postcss-simple-vars', not a declaration
    if (isScssVariable(decl.prop))
        return false;
    return true;
}
